/* Shop.mn-ийн загвар */

body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
}

h1 { font-size: 36px; }

header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
}

.cart-count {
  background-color: #2563eb;
  color: #ffffff;
  border-radius: 999px;
  padding: 2px 10px;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 16px;
}

.search,
.sort {
  padding: 10px 12px;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
  font-size: 16px;
  background-color: #ffffff;
  color: #18181b;
}

.search { flex: 1 1 220px; }

.product-card {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
}

.product-card img { max-width: 100%; height: auto; }

.btn-add {
  background-color: #2563eb;
  color: #ffffff;
  padding: 10px 16px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
}

.product-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

.cart ul {
  list-style: none;
  padding: 0;
}

.cart li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px solid #e4e4e7;
}

.btn-remove {
  background-color: #ffffff;
  color: #b91c1c;
  border: 1px solid #fecaca;
  border-radius: 6px;
  padding: 4px 10px;
  cursor: pointer;
}

@media (min-width: 768px) {
  .product-grid { grid-template-columns: 1fr 1fr; }
  header { flex-direction: row; justify-content: space-between; }
}

// Shop.mn — JavaScript

const STORAGE_KEY = "shopmn-cart";

const products = [
  { id: 1, name: "Монгол дээл", price: 129000, image: "images/deel.jpg" },
  { id: 2, name: "Малгай", price: 45000, image: "images/malgai.jpg" },
  { id: 3, name: "Гутал", price: 89000, image: "images/gutal.jpg" },
];

const grid = document.querySelector('[data-testid="grid"]');
const searchInput = document.querySelector('[data-testid="search"]');
const sortSelect = document.querySelector('[data-testid="sort"]');
const cartList = document.querySelector('[data-testid="cart-items"]');
const cartCount = document.querySelector('[data-testid="cart-count"]');

function formatPrice(value) {
  return "₮ " + value.toLocaleString("en-US");
}

function renderProducts(list) {
  grid.textContent = "";

  list.forEach(function (product) {
    const cardEl = document.createElement("article");
    cardEl.className = "product-card";

    const image = document.createElement("img");
    image.src = product.image;
    image.alt = product.name;

    const name = document.createElement("h3");
    name.textContent = product.name;

    const price = document.createElement("p");
    price.className = "price";
    price.textContent = formatPrice(product.price);

    const button = document.createElement("button");
    button.className = "btn-add";
    button.dataset.testid = "add-to-cart";
    button.textContent = "Сагсанд хийх";
    button.addEventListener("click", function () {
      addToCart(product);
    });

    cardEl.append(image, name, price, button);
    grid.append(cardEl);
  });
}

function sortProducts(list, mode) {
  const copy = [...list];

  if (mode === "price-asc") {
    return copy.sort(function (a, b) {
      return a.price - b.price;
    });
  }

  if (mode === "price-desc") {
    return copy.sort(function (a, b) {
      return b.price - a.price;
    });
  }

  return copy;
}

function applyFilters() {
  const query = searchInput.value.trim().toLowerCase();

  const found = products.filter(function (product) {
    return product.name.toLowerCase().includes(query);
  });

  renderProducts(sortProducts(found, sortSelect.value));
}

function loadCart() {
  const raw = localStorage.getItem(STORAGE_KEY);
  if (!raw) return [];

  try {
    const saved = JSON.parse(raw);
    return Array.isArray(saved) ? saved : [];
  } catch (error) {
    return [];
  }
}

function saveCart() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(cart));
}

let cart = loadCart();

function addToCart(product) {
  const existing = cart.find(function (item) {
    return item.id === product.id;
  });

  if (existing) {
    existing.quantity += 1;
  } else {
    cart.push({ id: product.id, name: product.name, price: product.price, quantity: 1 });
  }

  saveCart();
  renderCart();
}

function renderCart() {
  cartList.textContent = "";

  let count = 0;
  cart.forEach(function (item) {
    count += item.quantity;

    const row = document.createElement("li");

    const label = document.createElement("span");
    label.textContent = item.name + " × " + item.quantity;

    const removeButton = document.createElement("button");
    removeButton.className = "btn-remove";
    removeButton.dataset.testid = "remove";
    removeButton.dataset.id = String(item.id);
    removeButton.textContent = "Хасах";

    row.append(label, removeButton);
    cartList.append(row);
  });

  cartCount.textContent = String(count);
}

searchInput.addEventListener("input", applyFilters);
sortSelect.addEventListener("change", applyFilters);

// энд бичнэ үү

applyFilters();
renderCart();

